// Do not edit this file as it will be overwritten if HAMR codegen is rerun

//! Property too_cold_heats -- Pre-Assert and Next-Assert VCs for every schema transition.
//! Each proof fn has an empty body: Verus discharges `requires ==> ensures`
//! via SMT; add proof hints in the body if a VC does not discharge.

#![allow(non_snake_case)]
#![allow(unused_variables)]
#![allow(unused_imports)]

use vstd::prelude::*;

use crate::assertions::*;
use crate::too_cold_heats::assertions::*;
use crate::contracts::*;
use crate::system_state::SystemState;
use crate::write_frames::*;

verus! {

/** VC[1]: Pre-Assert -- START |- OI compute assumes */
pub proof fn vc_pre_assert_oi(st: SystemState)
  requires
    sys_assert_too_cold_heats_START(st),
  ensures
    true /* no assertions at out-places */,
{}

/** VC[2]: Next-Assert (task) -- START + frames + OI postcondition + OI's integration guarantees |- after_oi.
  * The integration guarantees hold by OI's own contract proof (its component crate). */
pub proof fn vc_next_assert_task_oi(pre: SystemState, post: SystemState)
  requires
    sys_assert_too_cold_heats_START(pre),
    oi_local_write_frame(pre, post),
    oi_global_write_frame(pre, post),
    oi::integration_spec_LDT_LE_UDT_guarantee(post.desired_temp),
  ensures
    sys_assert_too_cold_heats_after_oi(post),
{}

/** VC[3]: Pre-Assert -- after_oi |- SENSOR compute assumes */
pub proof fn vc_pre_assert_sensor(st: SystemState)
  requires
    sys_assert_too_cold_heats_after_oi(st),
  ensures
    true /* no assertions at out-places */,
{}

/** VC[4]: Next-Assert (task) -- after_oi + frames + SENSOR postcondition + SENSOR's integration guarantees |- after_sensor.
  * The integration guarantees hold by SENSOR's own contract proof (its component crate). */
pub proof fn vc_next_assert_task_sensor(pre: SystemState, post: SystemState)
  requires
    sys_assert_too_cold_heats_after_oi(pre),
    sensor_local_write_frame(pre, post),
    sensor_global_write_frame(pre, post),
    sensor::integration_spec_temp_range_guarantee(post.sensedTemp),
  ensures
    sys_assert_too_cold_heats_after_sensor(post),
{}

/** VC[5]: Pre-Assert -- after_sensor |- THERM compute assumes.
  * THERM's integration assumes are not obligations here; they are discharged
  * per-connection in vc_integration.rs (upstream guarantee => assume). */
pub proof fn vc_pre_assert_therm(st: SystemState)
  requires
    sys_assert_too_cold_heats_after_sensor(st),
  ensures
    therm::compute_spec_INV_CSP_assume(st.setPoints),
{}

/** VC[6]: Next-Assert (task) -- after_sensor + frames + THERM postcondition + THERM's integration assumes |- after_therm.
  * The integration assumes are discharged per-connection in vc_integration.rs (upstream guarantee => assume). */
pub proof fn vc_next_assert_task_therm(pre: SystemState, post: SystemState)
  requires
    sys_assert_too_cold_heats_after_sensor(pre),
    therm_local_write_frame(pre, post),
    therm_global_write_frame(pre, post),
    therm::compute_spec_latchSetPointsOnEvent_guarantee(post.setPoints, pre.desired_temp),
    therm::compute_spec_latchSetPointsNoEvent_guarantee(pre.setPoints, post.setPoints, pre.desired_temp),
    therm::compute_spec_invCSPMaintained_guarantee(post.setPoints),
    therm::compute_spec_noTriggerNoChange_guarantee(pre.lastCmd, post.lastCmd, pre.tempChanged, pre.desired_temp),
    therm::compute_spec_REQ_THERM_2_guarantee(post.setPoints, post.lastCmd, pre.tempChanged, pre.desired_temp, pre.sensedTemp),
    therm::compute_spec_REQ_THERM_3_guarantee(post.setPoints, post.lastCmd, pre.tempChanged, pre.desired_temp, pre.sensedTemp),
    therm::compute_spec_REQ_THERM_4_guarantee(pre.lastCmd, post.setPoints, post.lastCmd, pre.tempChanged, pre.desired_temp, pre.sensedTemp),
    therm::compute_spec_mustSendOnChange_guarantee(pre.lastCmd, post.lastCmd, post.heatCmd),
    therm::compute_spec_noSendNoChange_guarantee(pre.lastCmd, post.lastCmd, post.heatCmd),
    therm::integration_spec_ASSM_CT_Range_assume(pre.sensedTemp),
    therm::integration_spec_ASSM_LDT_LE_UDT_assume(pre.desired_temp),
  ensures
    sys_assert_too_cold_heats_after_therm(post),
{}

/** VC[7]: Pre-Assert -- after_therm |- HS compute assumes */
pub proof fn vc_pre_assert_hs(st: SystemState)
  requires
    sys_assert_too_cold_heats_after_therm(st),
  ensures
    true /* no assertions at out-places */,
{}

/** VC[8]: Next-Assert (task) -- after_therm + frames + HS postcondition |- after_hs */
pub proof fn vc_next_assert_task_hs(pre: SystemState, post: SystemState)
  requires
    sys_assert_too_cold_heats_after_therm(pre),
    hs_local_write_frame(pre, post),
    hs_global_write_frame(pre, post),
    hs::compute_spec_HS_latch_cmd_guarantee(post.heaterState, pre.heatCmd),
    hs::compute_spec_HS_hold_cmd_guarantee(pre.heaterState, post.heaterState, pre.heatCmd),
  ensures
    sys_assert_too_cold_heats_after_hs(post),
{}

/** VC[9]: Next-Assert (control point) -- after_hs |- END (state unchanged) */
pub proof fn vc_next_assert_skip_t4(st: SystemState)
  requires
    sys_assert_too_cold_heats_after_hs(st),
  ensures
    sys_assert_too_cold_heats_END(st),
{}

} // verus!
